case_facts = {
    "order_id": "7734",
    "amount_requested": 84.50,
    "currency": "USD",
    "deadline": "2025-03-15",
    "status": "pending_refund",
    "customer_stated_expectation": "full refund before 3/15",
}

def build_prompt(summarized_history, case_facts, new_message):
    # case_facts always goes in full, outside any summarization
    facts_block = "\n".join(f"- {k}: {v}" for k, v in case_facts.items())
    return f"""
Case facts (always exact, do not summarize):
{facts_block}

Conversation history (may be summarized):
{summarized_history}

New customer message:
{new_message}
"""

def update_case_facts(case_facts, tool_result):
    # every tool result containing a new fact updates the block
    # instead of getting buried in the history that gets summarized later
    if "refund_amount" in tool_result:
        case_facts["amount_requested"] = tool_result["refund_amount"]
    return case_facts
